def loc(name):
    try:
        g = primitives.call(name='submit_capx_action', action='locate_object_for_grasp', native_api=True, parameters={'object_name': name})
        o = g.output['native_api_result']
        p = o.get('pose')
        pv = p[0]['values'] if p else None
        ext = None
        if p and len(p) > 2 and p[2] is not None:
            try:
                ext = p[2]['values']
            except Exception:
                ext = None
        print(name, o.get('located'), 'pose', pv, 'ext', ext, 'ncand', len(o.get('grasp_candidates') or []))
        return o
    except Exception as e:
        print(name, 'err', str(e)[:200])
        return None
L = {}
for nm in ['yellow screwdriver', 'orange drill', 'black flashlight']:
    L[nm] = loc(nm)
